import { useEffect, useState } from "react";
import { Link, useLocation, useParams } from "wouter";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { AlertCircle, ArrowLeft, ArrowRight, CarFront, Check, ChevronRight, CircleDot, ClipboardCheck, ImagePlus, LockKeyhole, Plus, RefreshCw, Send, ShieldCheck, Sparkles, Store, UploadCloud, Wrench, X } from "lucide-react";
import { GuberLayout } from "@/components/guber-layout";
import { BizLayout } from "@/components/biz-layout";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { Card } from "@/components/ui/card";
import { Checkbox } from "@/components/ui/checkbox";
import { apiRequest } from "@/lib/queryClient";
import { uploadToCloudinarySigned } from "@/lib/cloudinary-upload";
import { compressImageToDataUrl } from "@/lib/image-compress";
import { useToast } from "@/hooks/use-toast";

const DISCLOSURE = "This is a preliminary visual assessment, not a CCC ONE estimate and not a final estimate, diagnosis, repair authorization, insurer submission, or guaranteed price. Physical inspection, teardown, parts pricing, OEM procedures, taxes, fees, and shop approval may change it.";
const shell = "min-h-[100dvh] bg-[hsl(156_28%_97%)] text-[hsl(174_35%_13%)]";
const panel = "rounded-2xl border border-[hsl(158_18%_80%)] bg-white shadow-[0_8px_30px_rgba(16,73,62,.06)]";

type Estimate = any;
type Shop = any;

function ErrorState({ message, retry }: { message: string; retry?: () => void }) {
  return <Card className="p-6 text-center border-red-200 bg-red-50/60"><AlertCircle className="mx-auto mb-2 h-6 w-6 text-red-600" /><p className="font-semibold">{message}</p>{retry && <Button onClick={retry} variant="outline" className="mt-4 min-h-11"><RefreshCw className="mr-2 h-4 w-4" /> Try again</Button>}</Card>;
}
function SectionTitle({ eyebrow, title, detail }: { eyebrow: string; title: string; detail?: string }) {
  return <div className="mb-5"><p className="font-mono text-[10px] font-bold tracking-[.18em] text-primary uppercase">{eyebrow}</p><h1 className="mt-1 font-display text-2xl font-black tracking-tight sm:text-3xl">{title}</h1>{detail && <p className="mt-2 max-w-xl text-sm leading-relaxed text-muted-foreground">{detail}</p>}</div>;
}
function Status({ value }: { value: string }) {
  const labels: Record<string, string> = { draft: "Draft", shared: "Shared with shops", responded: "Responses ready", accepted: "Shop accepted", expired: "Expired", new: "New", viewed: "Viewed", declined: "Declined", not_selected: "Not selected", matched: "Matched" };
  return <Badge variant="outline" className="rounded-full border-primary/25 bg-primary/5 text-primary">{labels[value] || value}</Badge>;
}
function Layout({ children, business = false }: { children: React.ReactNode; business?: boolean }) {
  return business ? <BizLayout>{children}</BizLayout> : <GuberLayout showBack backHref="/dashboard">{children}</GuberLayout>;
}
function Field({ label, children }: { label: string; children: React.ReactNode }) {
  return <label className="grid gap-1.5 text-sm font-semibold">{label}{children}</label>;
}
function estimateTitle(e: Estimate) { return [e?.vehicle?.year, e?.vehicle?.make, e?.vehicle?.model].filter(Boolean).join(" ") || "Vehicle assessment"; }
function range(low: any, high: any, suffix = "") { return low == null && high == null ? "Unknown" : `${low ?? "?"}–${high ?? "?"}${suffix}`; }

export default function RepairMatch() {
  const path = window.location.pathname;
  if (path === "/repairmatch/new") return <NewEstimate />;
  if (path.startsWith("/repairmatch/") && path !== "/repairmatch/new") return <EstimateDetail />;
  if (path === "/biz/repairmatch") return <ShopWorkspace />;
  if (path.startsWith("/biz/repairmatch/")) return <ShopOpportunity />;
  return <RepairMatchHome />;
}

function RepairMatchHome() {
  const { toast } = useToast();
  const { data, isLoading, isError, refetch } = useQuery<Estimate[]>({ queryKey: ["/api/repairmatch/estimates"] });
  const estimates = data || [];
  return <Layout><main className={`${shell} px-4 py-7 sm:px-8`}><div className="mx-auto max-w-5xl">
    <div className="mb-8 flex items-start justify-between gap-4"><SectionTitle eyebrow="GUBER / REPAIRMATCH" title="Your repair timeline" detail="Document the damage once. Keep control while qualified collision shops come to you." /><Link href="/repairmatch/new"><Button className="min-h-11 shrink-0 rounded-xl"><Plus className="mr-2 h-4 w-4" /> Start</Button></Link></div>
    <Card className="mb-7 overflow-hidden border-0 bg-[hsl(174_35%_13%)] text-white"><div className="grid gap-6 p-6 sm:grid-cols-[1.4fr_1fr] sm:p-8"><div><Badge className="border-primary/40 bg-primary/15 text-primary-foreground">Collision repair concierge</Badge><h2 className="mt-4 max-w-lg font-display text-3xl font-black tracking-tight sm:text-4xl">One clear record after a stressful moment.</h2><p className="mt-3 max-w-md text-sm leading-relaxed text-white/70">Upload 3–10 photos, get a preliminary visual assessment, then decide if one shop or nearby shops should review it.</p><Link href="/repairmatch/new"><Button className="mt-6 min-h-11 rounded-xl bg-primary text-primary-foreground hover:bg-primary/90">Create a repair record <ArrowRight className="ml-2 h-4 w-4" /></Button></Link></div><div className="grid grid-cols-2 gap-3 self-end"><div className="rounded-xl border border-white/10 bg-white/5 p-4"><ShieldCheck className="mb-3 h-5 w-5 text-primary" /><p className="text-sm font-bold">Private by default</p><p className="mt-1 text-xs text-white/55">Contact stays masked until you accept a shop.</p></div><div className="rounded-xl border border-white/10 bg-white/5 p-4"><ClipboardCheck className="mb-3 h-5 w-5 text-[hsl(39_82%_57%)]" /><p className="text-sm font-bold">Your call</p><p className="mt-1 text-xs text-white/55">No automatic publication or lowest-price ranking.</p></div></div></div></Card>
    {isLoading ? <div className="grid gap-3">{[1,2,3].map(i => <div key={i} className={`${panel} h-24 animate-pulse bg-muted`} />)}</div> : isError ? <ErrorState message="Repair records could not load." retry={() => refetch()} /> : estimates.length === 0 ? <Card className={`${panel} border-dashed p-10 text-center`}><CarFront className="mx-auto mb-3 h-8 w-8 text-primary" /><h2 className="font-display text-xl font-bold">No repair records yet</h2><p className="mx-auto mt-2 max-w-sm text-sm text-muted-foreground">If you have a collision, start with the facts you can see. Your draft stays saved while you work.</p><Link href="/repairmatch/new"><Button className="mt-5 min-h-11 rounded-xl">Start a repair record</Button></Link></Card> : <div className="grid gap-3">{estimates.map(e => <Link key={e.id} href={`/repairmatch/${e.id}`} className={`${panel} group flex min-h-24 items-center gap-4 p-4 transition-colors hover:border-primary/50`}><div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl bg-primary/10 text-primary"><CarFront className="h-5 w-5" /></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h2 className="font-display font-bold">{estimateTitle(e)}</h2><Status value={e.status} /></div><p className="mt-1 text-xs text-muted-foreground">{e.incident?.date || "Incident date not added"} · {e.photo_urls?.length || 0} photos</p></div><ChevronRight className="h-5 w-5 text-muted-foreground transition-transform group-hover:translate-x-1" /></Link>)}</div>}
  </div></main></Layout>;
}

function NewEstimate() {
  const [, navigate] = useLocation(); const { toast } = useToast(); const qc = useQueryClient();
  const [step, setStep] = useState(1); const [busy, setBusy] = useState(false); const [photos, setPhotos] = useState<{ id: string; url: string; name: string; progress: number; error?: string }[]>([]);
  const [vehicle, setVehicle] = useState({ year: "", make: "", model: "", vin: "", mileage: "", zip: "" });
  const [incident, setIncident] = useState({ description: "", date: "", damageAreas: "", drivable: "yes", towing: "no" });
  const [contact, setContact] = useState({ name: "", phone: "", email: "" }); const [disclosure, setDisclosure] = useState(false);
  const update = (setter: any, key: string) => (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => setter((x: any) => ({ ...x, [key]: e.target.value }));
  async function addFiles(files: FileList | null) {
    if (!files) return; const incoming = Array.from(files).slice(0, 10 - photos.length);
    for (const file of incoming) {
      const photoId = crypto.randomUUID(); const item = { id: photoId, url: "", name: file.name, progress: 1 }; setPhotos(p => [...p, item]);
      try { const compressed = await compressImageToDataUrl(file); const blob = await (await fetch(compressed)).blob(); const result = await uploadToCloudinarySigned(blob, { resourceType: "image", fileName: file.name, onProgress: progress => setPhotos(p => p.map(x => x.id === photoId ? { ...x, progress } : x)) }); setPhotos(p => p.map(x => x.id === photoId ? { ...x, url: result.url, progress: 100 } : x)); }
      catch (err: any) { setPhotos(p => p.map(x => x.id === photoId ? { ...x, error: err.message || "Upload failed", progress: 0 } : x)); }
    }
  }
  async function create() {
    if (photos.length < 3 || photos.some(p => !p.url)) return toast({ title: "Add 3 successful photos", description: "Each photo needs to finish uploading before you continue.", variant: "destructive" });
    setBusy(true); try { const res = await apiRequest("POST", "/api/repairmatch/estimates", { vehicle, incident, photoUrls: photos.map(p => p.url), locationApprox: vehicle.zip, customerContact: contact }); const e = await res.json(); try { const key = crypto.randomUUID(); await apiRequest("POST", `/api/repairmatch/estimates/${e.id}/generate`, { idempotencyKey: key }, { "Idempotency-Key": key }); } catch (err: any) { toast({ title: "Draft saved; analysis needs another try", description: err.message || "Your photos are safe.", variant: "destructive" }); } qc.invalidateQueries({ queryKey: ["/api/repairmatch/estimates"] }); navigate(`/repairmatch/${e.id}`); } catch (err: any) { toast({ title: "We could not save this record", description: err.message || "Please try again.", variant: "destructive" }); } finally { setBusy(false); }
  }
  const steps = ["Vehicle", "Incident", "Photos", "Review"];
  return <Layout><main className={`${shell} px-4 py-6 pb-28 sm:px-8`}><div className="mx-auto max-w-3xl"><Link href="/repairmatch" className="mb-6 inline-flex min-h-11 items-center gap-2 text-sm font-semibold text-muted-foreground"><ArrowLeft className="h-4 w-4" /> Repair timeline</Link><SectionTitle eyebrow={`STEP ${step} OF 4`} title="Build your repair record" detail="Move at your pace. We save the facts and photos together before asking shops to review." /><div className="mb-7 flex items-center gap-2">{steps.map((s, i) => <div key={s} className="flex flex-1 items-center gap-2"><div className={`grid h-8 w-8 shrink-0 place-items-center rounded-full text-xs font-bold ${i + 1 <= step ? "bg-primary text-primary-foreground" : "bg-muted text-muted-foreground"}`}>{i + 1 < step ? <Check className="h-4 w-4" /> : i + 1}</div><span className="hidden text-xs font-semibold sm:block">{s}</span>{i < 3 && <div className={`h-px flex-1 ${i + 1 < step ? "bg-primary" : "bg-border"}`} />}</div>)}</div>
  <Card className={`${panel} p-5 sm:p-7`}>
    {step === 1 && <div className="grid gap-4"><h2 className="font-display text-xl font-bold">Which vehicle was involved?</h2><div className="grid gap-4 sm:grid-cols-3"><Field label="Year *"><Input value={vehicle.year} onChange={update(setVehicle, "year")} inputMode="numeric" /></Field><Field label="Make *"><Input value={vehicle.make} onChange={update(setVehicle, "make")} placeholder="Toyota" /></Field><Field label="Model *"><Input value={vehicle.model} onChange={update(setVehicle, "model")} placeholder="Camry" /></Field></div><div className="grid gap-4 sm:grid-cols-3"><Field label="VIN (optional)"><Input value={vehicle.vin} onChange={update(setVehicle, "vin")} /></Field><Field label="Mileage (optional)"><Input value={vehicle.mileage} onChange={update(setVehicle, "mileage")} inputMode="numeric" /></Field><Field label="ZIP for matching"><Input value={vehicle.zip} onChange={update(setVehicle, "zip")} inputMode="numeric" /></Field></div></div>}
    {step === 2 && <div className="grid gap-4"><h2 className="font-display text-xl font-bold">Tell us what happened</h2><Field label="What do you see?"><Textarea className="min-h-28" value={incident.description} onChange={update(setIncident, "description")} placeholder="Describe the impact and visible damage in your own words." /></Field><div className="grid gap-4 sm:grid-cols-2"><Field label="Incident date"><Input type="date" value={incident.date} onChange={update(setIncident, "date")} /></Field><Field label="Damage areas"><Input value={incident.damageAreas} onChange={update(setIncident, "damageAreas")} placeholder="Front bumper, driver door" /></Field><Field label="Can it be driven?"><select className="h-11 rounded-md border bg-background px-3" value={incident.drivable} onChange={update(setIncident, "drivable")}><option value="yes">Yes, carefully</option><option value="no">No</option><option value="unknown">Not sure</option></select></Field><Field label="Towing needed?"><select className="h-11 rounded-md border bg-background px-3" value={incident.towing} onChange={update(setIncident, "towing")}><option value="no">No</option><option value="yes">Yes</option><option value="unknown">Not sure</option></select></Field></div></div>}
    {step === 3 && <div className="grid gap-4"><div><h2 className="font-display text-xl font-bold">Show us the visible damage</h2><p className="mt-1 text-sm text-muted-foreground">Add 3–10 clear photos from different angles. Avoid personal documents or faces.</p></div><label className="flex min-h-32 cursor-pointer flex-col items-center justify-center rounded-xl border-2 border-dashed border-primary/35 bg-primary/5 text-center"><UploadCloud className="mb-2 h-7 w-7 text-primary" /><span className="font-semibold">Choose damage photos</span><span className="mt-1 text-xs text-muted-foreground">JPG, PNG or HEIC · up to 10</span><input type="file" accept="image/*" multiple className="sr-only" onChange={e => addFiles(e.target.files)} /></label><div className="grid grid-cols-3 gap-3 sm:grid-cols-5">{photos.map((p, i) => <div key={`${p.name}-${i}`} className="relative aspect-square overflow-hidden rounded-lg border bg-muted">{p.url ? <img src={p.url} alt={`Damage photo ${i + 1}`} className="h-full w-full object-cover" /> : <div className="grid h-full place-items-center p-2 text-center"><ImagePlus className="mx-auto h-5 w-5 text-muted-foreground" /><span className="mt-1 text-[10px]">{p.error || `${p.progress}% uploading`}</span></div>}<button type="button" className="absolute right-1 top-1 grid h-7 w-7 place-items-center rounded-full bg-black/65 text-white" onClick={() => setPhotos(x => x.filter((_, j) => j !== i))} aria-label={`Remove photo ${i + 1}`}><X className="h-3.5 w-3.5" /></button></div>)}</div>{photos.some(p => p.error) && <p className="text-sm text-red-700">Some photos failed. Remove them and retry, or choose another image.</p>}</div>}
    {step === 4 && <div className="grid gap-5"><div><h2 className="font-display text-xl font-bold">Review before analysis</h2><p className="mt-1 text-sm text-muted-foreground">Your contact details stay private. Shops only see approved information after distribution.</p></div><div className="grid gap-3 rounded-xl bg-muted/50 p-4 text-sm"><p><b>Vehicle:</b> {estimateTitle({ vehicle })}</p><p><b>Incident:</b> {incident.description || "No description added"}</p><p><b>Photos:</b> {photos.length} ready</p></div><Field label="Your name"><Input value={contact.name} onChange={update(setContact, "name")} /></Field><div className="grid gap-4 sm:grid-cols-2"><Field label="Phone"><Input value={contact.phone} onChange={update(setContact, "phone")} /></Field><Field label="Email"><Input value={contact.email} onChange={update(setContact, "email")} type="email" /></Field></div><label className="flex min-h-11 items-start gap-3 text-sm"><Checkbox checked={disclosure} onCheckedChange={v => setDisclosure(Boolean(v))} /><span>I understand this is a preliminary visual assessment and not a final price or repair authorization.</span></label><p className="rounded-lg border border-[hsl(39_82%_57%)]/40 bg-[hsl(39_82%_57%)]/10 p-3 text-xs leading-relaxed">{DISCLOSURE}</p></div>}
    <div className="mt-7 flex justify-between gap-3 border-t pt-5"><Button variant="outline" className="min-h-11 rounded-xl" onClick={() => setStep(s => Math.max(1, s - 1))} disabled={step === 1}>Back</Button>{step < 4 ? <Button className="min-h-11 rounded-xl" onClick={() => setStep(s => s + 1)} disabled={(step === 1 && (!vehicle.year || !vehicle.make || !vehicle.model)) || (step === 3 && (photos.length < 3 || photos.some(p => !p.url)))}>Continue <ArrowRight className="ml-2 h-4 w-4" /></Button> : <Button className="min-h-11 rounded-xl" onClick={create} disabled={busy || !disclosure}>{busy ? "Saving and analyzing…" : "Create preliminary assessment"}</Button>}</div>
  </Card></div></main></Layout>;
}

function LegacyEstimateDetail() {
  const { id } = useParams<{ id: string }>(); const { toast } = useToast(); const qc = useQueryClient(); const [zip, setZip] = useState(""); const [selected, setSelected] = useState<number | null>(null); const [mode, setMode] = useState<"single" | "nearby">("single");
  const { data: e, isLoading, isError, refetch } = useQuery<Estimate>({ queryKey: [`/api/repairmatch/estimates/${id}`], enabled: Boolean(id) }); const { data: shops } = useQuery<Shop[]>({ queryKey: [`/api/repairmatch/shops?zip=${zip}`], enabled: Boolean(zip) });
  useEffect(() => { if (e?.vehicle?.zip && !zip) setZip(e.vehicle.zip); }, [e?.vehicle?.zip, zip]);
  const action = useMutation({ mutationFn: async (payload: any) => apiRequest("POST", `/api/repairmatch/estimates/${id}/${payload.type}`, payload.body, payload.headers), onSuccess: () => { toast({ title: "RepairMatch updated" }); qc.invalidateQueries({ queryKey: [`/api/repairmatch/estimates/${id}`] }); }, onError: (x: Error) => toast({ title: "Could not complete that action", description: x.message, variant: "destructive" }) });
  const retryAnalysis = () => { const key = crypto.randomUUID(); action.mutate({ type: "generate", body: { idempotencyKey: key }, headers: { "Idempotency-Key": key } }); };
  if (isLoading) return <Layout><main className={`${shell} p-6`}><div className="mx-auto max-w-3xl space-y-3"><div className="h-9 w-2/3 animate-pulse rounded bg-muted" /><div className="h-56 animate-pulse rounded-2xl bg-muted" /></div></main></Layout>;
  if (isError || !e) return <Layout><main className={`${shell} p-6`}><div className="mx-auto max-w-3xl"><ErrorState message="This repair record is unavailable or expired." retry={() => refetch()} /></div></main></Layout>;
  const responded = (e.opportunities || []).filter((o: any) => o.status === "responded");
  return <Layout><main className={`${shell} px-4 py-7 sm:px-8`}><div className="mx-auto max-w-4xl"><Link href="/repairmatch" className="mb-6 inline-flex min-h-11 items-center gap-2 text-sm font-semibold text-muted-foreground"><ArrowLeft className="h-4 w-4" /> Repair timeline</Link><div className="flex flex-wrap items-end justify-between gap-3"><SectionTitle eyebrow="REPAIRMATCH RECORD" title={estimateTitle(e)} detail={`${e.incident?.date || "Incident"} · ${e.photo_urls?.length || 0} photos`} /><Status value={e.status} /></div><div className="grid gap-5 lg:grid-cols-[1fr_330px]"><div className="space-y-5"><Card className={`${panel} p-5`}><div className="flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-primary/10 text-primary"><Sparkles className="h-5 w-5" /></div><div><h2 className="font-display font-bold">Preliminary visual assessment</h2><p className="text-xs text-muted-foreground">Original AI findings · not a shop quote</p></div></div>{e.ai_result ? <><p className="mt-5 text-sm leading-relaxed">{e.ai_result.summary || "Visible damage has been organized for shop review."}</p><div className="mt-5 grid grid-cols-2 gap-3 sm:grid-cols-4">{[["Severity", e.ai_result.severity], ["Confidence", e.ai_result.confidence ? `${Math.round(e.ai_result.confidence * 100)}%` : "Unknown"], ["Body hours", `${e.ai_result.totals?.bodyHoursLow || 0}–${e.ai_result.totals?.bodyHoursHigh || 0}`], ["Inspection", e.ai_result.inspectionRequired?.length ? "Required" : "Review"]].map(([a,b]) => <div key={a} className="rounded-lg bg-muted/50 p-3"><p className="text-[10px] font-mono uppercase text-muted-foreground">{a}</p><p className="mt-1 font-bold capitalize">{b}</p></div>)}</div><div className="mt-5 overflow-x-auto"><table className="w-full text-left text-sm"><thead><tr className="border-b text-xs text-muted-foreground"><th className="pb-2">Visible component</th><th className="pb-2">Recommendation</th><th className="pb-2">Review</th></tr></thead><tbody>{(e.lines || []).map((l: any) => <tr key={l.id} className="border-b last:border-0"><td className="py-3 font-semibold">{l.component}</td><td className="py-3 capitalize">{l.recommendation}</td><td className="py-3">{l.inspection_required ? <Badge variant="outline" className="text-[10px]">Inspection needed</Badge> : "Visible"}</td></tr>)}</tbody></table></div></> : <p className="mt-5 text-sm text-muted-foreground">Analysis is not available yet. Your photos are preserved for another attempt.</p>}</Card><p className="text-xs leading-relaxed text-muted-foreground"><b>Permanent disclosure:</b> {e.disclosure || DISCLOSURE}</p></div><aside className="space-y-4"><Card className={`${panel} p-5`}><h2 className="font-display font-bold">Shop responses</h2><p className="mt-1 text-xs text-muted-foreground">Compare timing, service, warranty, and fit. RepairMatch does not rank shops by lowest price.</p>{e.status === "draft" && <div className="mt-5 grid gap-3"><Field label="ZIP for nearby shops"><Input value={zip} onChange={x => setZip(x.target.value)} placeholder="Enter ZIP" /></Field>{shops?.length ? shops.map(s => <button type="button" key={s.id} onClick={() => setSelected(s.id)} className={`flex min-h-16 items-center gap-3 rounded-xl border p-3 text-left ${selected === s.id ? "border-primary bg-primary/5" : "border-border"}`}><Store className="h-5 w-5 text-primary" /><span className="flex-1"><b>{s.company_name}</b><small className="block text-muted-foreground">{s.service_radius_miles || 25} mile service area</small></span>{selected === s.id && <Check className="h-4 w-4 text-primary" />}</button>) : zip ? <p className="rounded-lg bg-muted p-3 text-xs">No participating shops found for that ZIP. Try another ZIP or choose nearby matching.</p> : null}<label className="flex min-h-11 items-start gap-3 text-sm"><input type="radio" checked={mode === "single"} onChange={() => setMode("single")} /> Send to one selected shop</label><label className="flex min-h-11 items-start gap-3 text-sm"><input type="radio" checked={mode === "nearby"} onChange={() => setMode("nearby")} /> <span><b>Let nearby repair shops come to you</b><small className="mt-1 block text-xs text-muted-foreground">A capped set of eligible shops can review the same record. This is not an auction.</small></span></label><Button className="min-h-11 rounded-xl" disabled={action.isPending || !e.ai_result || (mode === "single" && !selected)} onClick={() => action.mutate({ type: "distribute", body: { mode, shopProfileId: selected, zip, approveSharing: true } })}><Send className="mr-2 h-4 w-4" /> Share for review</Button></div>}{responded.length ? <div className="mt-4 grid gap-3">{responded.map((o: any) => { const r = (e.responses || []).find((x: any) => x.opportunity_id === o.id); return <div key={o.id} className="rounded-xl border p-3"><div className="flex items-center gap-2"><Store className="h-4 w-4 text-primary" /><b className="flex-1">{o.company_name}</b><Status value={o.status} /></div><p className="mt-2 text-sm">{r?.customer_note || "The shop has reviewed your record."}</p><p className="mt-2 text-xs text-muted-foreground">{r?.expected_repair_timing || "Timing to be discussed"} · {r?.warranty || "Warranty details available from shop"}</p><Button className="mt-3 min-h-11 w-full rounded-xl" onClick={() => action.mutate({ type: "accept-shop", body: { opportunityId: o.id } })}>Accept this shop</Button></div>})}</div> : e.status !== "draft" && <p className="mt-5 rounded-lg bg-muted p-3 text-sm text-muted-foreground">Waiting for participating shops to respond.</p>}</Card><div className="flex items-center gap-2 rounded-xl border border-primary/20 bg-primary/5 p-3 text-xs"><LockKeyhole className="h-4 w-4 shrink-0 text-primary" />Contact details remain masked until you accept a shop.</div></aside></div></div></main></Layout>;
}

function ShopWorkspace() {
  const { data, isLoading, isError, refetch } = useQuery<any[]>({ queryKey: ["/api/repairmatch/shop/opportunities"] }); const { data: profile } = useQuery<any>({ queryKey: ["/api/repairmatch/shop/profile"] }); const [active, setActive] = useState(true); const [collisionBody, setCollisionBody] = useState(true); const [zip, setZip] = useState(""); const [radius, setRadius] = useState("25"); const [profileInitialized, setProfileInitialized] = useState(false); const { toast } = useToast();
  useEffect(() => { if (profile && !profileInitialized) { setActive(Boolean(profile.active)); setCollisionBody(Boolean(profile.collision_body)); setZip(profile.service_zip || ""); setRadius(String(profile.service_radius_miles || 25)); setProfileInitialized(true); } }, [profile, profileInitialized]);
  const save = useMutation({ mutationFn: () => apiRequest("PUT", "/api/repairmatch/shop/profile", { active, collisionBody, serviceZip: zip, serviceRadiusMiles: Number(radius), capabilities: ["collision repair", "paint and refinish"] }), onSuccess: () => toast({ title: "RepairMatch profile saved" }), onError: (e: Error) => toast({ title: "Could not save profile", description: e.message, variant: "destructive" }) });
  return <Layout business><main className="mx-auto max-w-5xl"><div className="flex flex-wrap items-end justify-between gap-3"><SectionTitle eyebrow="BUSINESS / REPAIRMATCH" title="Repair opportunities" detail="Review customer-approved collision records with a precise, separate shop workspace." /><Link href="/biz/dashboard"><Button variant="outline" className="min-h-11 rounded-xl">Business dashboard</Button></Link></div><Card className="mb-6 border-primary/25 bg-primary/5 p-5"><div className="flex items-start gap-3"><Wrench className="mt-1 h-5 w-5 text-primary" /><div className="flex-1"><h2 className="font-display font-bold">Participating shop profile</h2><p className="mt-1 text-sm text-muted-foreground">Only verified businesses with collision/body capability can receive opportunities.</p><div className="mt-4 grid gap-3 sm:grid-cols-3"><Field label="Service ZIP"><Input value={zip} onChange={e => setZip(e.target.value)} /></Field><Field label="Radius (miles)"><Input value={radius} onChange={e => setRadius(e.target.value)} inputMode="numeric" /></Field><Field label="Collision/body repair"><select className="h-11 rounded-md border bg-background px-3" value={collisionBody ? "yes" : "no"} onChange={e => setCollisionBody(e.target.value === "yes")}><option value="yes">Enabled</option><option value="no">Disabled</option></select></Field></div><div className="mt-4 flex flex-wrap items-center gap-3"><Button onClick={() => save.mutate()} className="min-h-11 rounded-xl" disabled={save.isPending || !zip}>Save participation settings</Button><label className="flex min-h-11 items-center gap-2 text-sm"><Checkbox checked={active} onCheckedChange={v => setActive(Boolean(v))} /> Accept new opportunities</label></div></div></div></Card>{isLoading ? <div className="h-32 animate-pulse rounded-2xl bg-muted" /> : isError ? <ErrorState message="Opportunities could not load." retry={() => refetch()} /> : !data?.length ? <Card className={`${panel} border-dashed p-10 text-center`}><CircleDot className="mx-auto mb-3 h-7 w-7 text-muted-foreground" /><h2 className="font-display text-xl font-bold">No opportunities yet</h2><p className="mt-2 text-sm text-muted-foreground">Keep your service area current. New customer-approved records will appear here.</p></Card> : <div className="grid gap-3">{data.map(o => <Link key={o.id} href={`/biz/repairmatch/${o.id}`} className={`${panel} flex min-h-24 items-center gap-4 p-4 transition-colors hover:border-primary/50`}><div className="grid h-11 w-11 place-items-center rounded-xl bg-[hsl(39_82%_57%)]/15 text-[hsl(39_60%_37%)]"><CarFront className="h-5 w-5" /></div><div className="flex-1"><div className="flex flex-wrap items-center gap-2"><h2 className="font-display font-bold">{estimateTitle(o)}</h2><Status value={o.status} /></div><p className="mt-1 text-xs text-muted-foreground">{o.location_approx || "Approximate location withheld"} · {o.incident?.description || "Collision record"}</p></div><ChevronRight className="h-5 w-5 text-muted-foreground" /></Link>)}</div>}</main></Layout>;
}

function LegacyShopOpportunity() {
  // Response fields are initialized from the server once; subsequent refetches never overwrite edits.
  const { id } = useParams<{ id: string }>(); const { toast } = useToast(); const qc = useQueryClient(); const { data: o, isLoading, isError, refetch } = useQuery<any>({ queryKey: [`/api/repairmatch/shop/opportunities/${id}`] }); const [form, setForm] = useState({ availability: "", inspectionRequest: "", expectedRepairTiming: "", warranty: "", towingAvailable: false, partsApproach: "", capabilitiesNote: "", customerNote: "" });
  useEffect(() => { if (o?.response) setForm(x => x.availability || x.customerNote ? x : { availability: o.response.availability || "", inspectionRequest: o.response.inspection_request || "", expectedRepairTiming: o.response.expected_repair_timing || "", warranty: o.response.warranty || "", towingAvailable: Boolean(o.response.towing_available), partsApproach: o.response.parts_approach || "", capabilitiesNote: o.response.capabilities_note || "", customerNote: o.response.customer_note || "" }); }, [o?.response]);
  const update = (key: string) => (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => setForm(x => ({ ...x, [key]: e.target.value }));
  const save = useMutation({ mutationFn: (status: string) => apiRequest("PUT", `/api/repairmatch/shop/opportunities/${id}/response`, { ...form, status, reviewedLines: (o?.lines || []).map((l: any) => ({ estimateLineId: l.id, component: l.component, recommendation: l.recommendation, inspectionRequired: l.inspection_required, notes: l.notes })) }), onSuccess: () => { toast({ title: "Response saved" }); qc.invalidateQueries({ queryKey: [`/api/repairmatch/shop/opportunities/${id}`] }); }, onError: (e: Error) => toast({ title: "Could not save response", description: e.message, variant: "destructive" }) });
  if (isLoading) return <Layout business><div className="mx-auto max-w-4xl h-56 animate-pulse rounded-2xl bg-muted" /></Layout>;
  if (isError || !o) return <Layout business><div className="mx-auto max-w-4xl"><ErrorState message="This opportunity is unavailable or expired." retry={() => refetch()} /></div></Layout>;
  return <Layout business><main className="mx-auto max-w-5xl"><Link href="/biz/repairmatch" className="mb-6 inline-flex min-h-11 items-center gap-2 text-sm font-semibold text-muted-foreground"><ArrowLeft className="h-4 w-4" /> Opportunities</Link><div className="flex flex-wrap items-end justify-between gap-3"><SectionTitle eyebrow="SHOP REVIEW" title={estimateTitle(o)} detail="Customer-approved information · exact contact stays hidden until acceptance" /><Status value={o.status} /></div><div className="grid gap-5 lg:grid-cols-[1fr_360px]"><Card className={`${panel} p-5`}><div className="mb-5 flex items-center justify-between"><div><h2 className="font-display text-xl font-bold">Original preliminary lines</h2><p className="text-xs text-muted-foreground">Read-only AI record. Your reviewed values are saved separately.</p></div><Badge variant="outline">AI source</Badge></div><div className="grid gap-3">{(o.lines || []).map((l: any) => <div key={l.id} className="rounded-xl border p-4"><div className="flex items-center gap-2"><span className="font-semibold">{l.component}</span><Badge className="ml-auto bg-primary/10 text-primary" variant="outline">{l.recommendation}</Badge></div><p className="mt-2 text-xs text-muted-foreground">{l.notes || "Visible finding; confirm during physical inspection."}</p></div>)}</div><p className="mt-5 rounded-lg bg-muted p-3 text-xs leading-relaxed"><b>Privacy:</b> Customer contact and exact address are not available at this stage.</p></Card><Card className={`${panel} p-5`}><h2 className="font-display text-xl font-bold">Your response</h2><p className="mt-1 text-xs text-muted-foreground">Give the customer useful next steps, not a promised final price.</p><div className="mt-5 grid gap-4"><Field label="Availability"><Input value={form.availability} onChange={update("availability")} placeholder="Next available inspection" /></Field><Field label="Inspection request"><Textarea value={form.inspectionRequest} onChange={update("inspectionRequest")} placeholder="What should the customer bring or expect?" /></Field><Field label="Expected repair timing"><Input value={form.expectedRepairTiming} onChange={update("expectedRepairTiming")} placeholder="Usually 5–7 business days after inspection" /></Field><Field label="Warranty"><Textarea value={form.warranty} onChange={update("warranty")} placeholder="Your workmanship warranty terms" /></Field><label className="flex min-h-11 items-center gap-3 text-sm"><Checkbox checked={form.towingAvailable} onCheckedChange={v => setForm(x => ({ ...x, towingAvailable: Boolean(v) }))} /> Towing coordination available</label><Field label="Parts approach"><Input value={form.partsApproach} onChange={update("partsApproach")} placeholder="OEM, aftermarket, or customer choice" /></Field><Field label="Capabilities note"><Textarea value={form.capabilitiesNote} onChange={update("capabilitiesNote")} /></Field><Field label="Note for customer"><Textarea value={form.customerNote} onChange={update("customerNote")} placeholder="A clear, reassuring message" /></Field><div className="grid gap-2 sm:grid-cols-2"><Button variant="outline" className="min-h-11 rounded-xl" onClick={() => save.mutate("declined")} disabled={save.isPending}>Decline</Button><Button className="min-h-11 rounded-xl" onClick={() => save.mutate("sent")} disabled={save.isPending}>{save.isPending ? "Saving…" : "Send reviewed response"} <Send className="ml-2 h-4 w-4" /></Button></div><Button variant="ghost" className="min-h-11 rounded-xl" onClick={() => save.mutate("draft")} disabled={save.isPending}>Save draft</Button></div></Card></div></main></Layout>;
}

function EstimateDetail() {
  const { id } = useParams<{ id: string }>();
  const { data: e, isLoading, isError, refetch } = useQuery<Estimate>({ queryKey: [`/api/repairmatch/estimates/${id}`], enabled: Boolean(id) });
  const { toast } = useToast();
  const qc = useQueryClient();
  const [zip, setZip] = useState("");
  const [selected, setSelected] = useState<number | null>(null);
  const [mode, setMode] = useState<"single" | "nearby">("single");
  const [shareApproved, setShareApproved] = useState(false);
  const { data: shops = [] } = useQuery<Shop[]>({
    queryKey: [`/api/repairmatch/shops?zip=${zip}`],
    enabled: Boolean(zip),
  });
  const action = useMutation({
    mutationFn: (p: any) => apiRequest("POST", `/api/repairmatch/estimates/${id}/${p.type}`, p.body, p.headers),
    onSuccess: () => { toast({ title: "RepairMatch updated" }); qc.invalidateQueries({ queryKey: [`/api/repairmatch/estimates/${id}`] }); },
    onError: (x: Error) => toast({ title: "Could not complete that action", description: x.message, variant: "destructive" }),
  });
  useEffect(() => { if (e?.vehicle?.zip && !zip) setZip(e.vehicle.zip); }, [e?.vehicle?.zip, zip]);
  if (isLoading) return <Layout><main className={`${shell} p-6`}><div className="mx-auto max-w-4xl h-56 animate-pulse rounded-2xl bg-muted" /></main></Layout>;
  if (isError || !e) return <Layout><main className={`${shell} p-6`}><div className="mx-auto max-w-4xl"><ErrorState message="This repair record is unavailable or expired." retry={() => refetch()} /></div></main></Layout>;
  const totals = e.ai_result?.totals || {};
  const responses = (e.responses || []).filter((r: any) => r.status === "sent" || r.status === "responded" || r.status === "accepted");
  const retry = () => { const key = crypto.randomUUID(); action.mutate({ type: "generate", body: { idempotencyKey: key }, headers: { "Idempotency-Key": key } }); };
  return <Layout><main className={`${shell} px-4 py-7 sm:px-8`}><div className="mx-auto max-w-5xl">
    <Link href="/repairmatch" className="mb-6 inline-flex min-h-11 items-center gap-2 text-sm font-semibold text-muted-foreground"><ArrowLeft className="h-4 w-4" /> Repair timeline</Link>
    <div className="flex flex-wrap items-end justify-between gap-3"><SectionTitle eyebrow="REPAIRMATCH RECORD" title={estimateTitle(e)} detail={`${e.incident?.date || "Incident"} · ${e.photo_urls?.length || 0} photos`} /><Status value={e.status} /></div>
    <div className="grid gap-5 lg:grid-cols-[1fr_340px]">
      <div className="space-y-5">
        <Card className={`${panel} p-5`}><div className="flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-primary/10 text-primary"><Sparkles className="h-5 w-5" /></div><div><h2 className="font-display font-bold">Preliminary visual assessment</h2><p className="text-xs text-muted-foreground">Original AI findings · not a shop quote</p></div></div>
          {e.ai_result ? <><p className="mt-5 text-sm leading-relaxed">{e.ai_result.summary || "Visible damage has been organized for shop review."}</p><div className="mt-5 grid grid-cols-2 gap-3 sm:grid-cols-3">{[["Severity", e.ai_result.severity || "unknown"], ["Confidence", e.ai_result.confidence ? `${Math.round(e.ai_result.confidence * 100)}%` : "Unknown"], ["Inspection", e.ai_result.inspectionRequired?.length ? "Required" : "Review"], ["Body labor", range(totals.bodyHoursLow, totals.bodyHoursHigh, " hrs")], ["Refinish labor", range(totals.refinishHoursLow, totals.refinishHoursHigh, " hrs")], ["Mechanical labor", range(totals.mechanicalHoursLow, totals.mechanicalHoursHigh, " hrs")], ["Total labor", range((totals.bodyHoursLow || 0) + (totals.refinishHoursLow || 0) + (totals.mechanicalHoursLow || 0), (totals.bodyHoursHigh || 0) + (totals.refinishHoursHigh || 0) + (totals.mechanicalHoursHigh || 0), " hrs")], ["Parts allowance", range(totals.partsAllowanceLow, totals.partsAllowanceHigh)]].map(([a,b]) => <div key={a} className="rounded-lg bg-muted/50 p-3"><p className="text-[10px] font-mono uppercase text-muted-foreground">{a}</p><p className="mt-1 font-bold capitalize">{b}</p></div>)}</div><div className="mt-5 overflow-x-auto"><table className="w-full text-left text-sm"><thead><tr className="border-b text-xs text-muted-foreground"><th className="pb-2">Visible component</th><th className="pb-2">Recommendation</th><th className="pb-2">Review</th></tr></thead><tbody>{(e.lines || []).map((l: any) => <tr key={l.id} className="border-b last:border-0"><td className="py-3 font-semibold">{l.component}</td><td className="py-3 capitalize">{l.recommendation}</td><td className="py-3">{l.inspection_required ? <Badge variant="outline" className="text-[10px]">Inspection needed</Badge> : "Visible"}</td></tr>)}</tbody></table></div></> : <div className="mt-5"><p className="text-sm text-muted-foreground">Analysis is not available yet. Your photos are preserved for another attempt.</p>{(e.generation_status === "failed" || e.generation_status !== "complete") && <Button className="mt-4 min-h-11 rounded-xl" onClick={retry} disabled={action.isPending}><RefreshCw className="mr-2 h-4 w-4" />{action.isPending ? "Retrying analysis…" : "Retry analysis"}</Button>}</div>}
        </Card><p className="text-xs leading-relaxed text-muted-foreground"><b>Permanent disclosure:</b> {e.disclosure || DISCLOSURE}</p>
      </div>
      <Card className={`${panel} p-5`}><h2 className="font-display font-bold">Shop responses</h2><p className="mt-1 text-xs text-muted-foreground">Compare timing, service, warranty, and fit. RepairMatch does not rank by lowest price.</p>{e.status === "draft" && <div className="mt-5 grid gap-3"><Field label="ZIP for nearby shops"><Input value={zip} onChange={x => setZip(x.target.value)} placeholder="Enter ZIP" /></Field>{mode === "single" && (shops.length ? shops.map(shop => <button type="button" key={shop.id} onClick={() => setSelected(shop.id)} className={`flex min-h-16 items-center gap-3 rounded-xl border p-3 text-left ${selected === shop.id ? "border-primary bg-primary/5" : "border-border"}`}><Store className="h-5 w-5 text-primary" /><span className="flex-1"><b>{shop.company_name}</b><small className="block text-muted-foreground">{shop.service_radius_miles || 25} mile service area</small></span>{selected === shop.id && <Check className="h-4 w-4 text-primary" />}</button>) : zip ? <p className="rounded-lg bg-muted p-3 text-xs">No participating shop is enrolled for that ZIP yet. You can use nearby matching or try another ZIP.</p> : null)}<Field label="Distribution"><select className="h-11 rounded-md border bg-background px-3" value={mode} onChange={x => setMode(x.target.value as "single" | "nearby")}><option value="single">Send to one selected shop</option><option value="nearby">Let nearby repair shops come to you</option></select></Field>{mode === "nearby" && <p className="rounded-lg bg-primary/5 p-3 text-xs text-muted-foreground">A capped set of eligible participating shops can review the same record and come to you. This is not a price auction.</p>}<label className="flex min-h-11 items-start gap-3 text-sm"><Checkbox checked={shareApproved} onCheckedChange={value => setShareApproved(Boolean(value))} /><span>I approve sharing the vehicle details, incident information, photos, approximate location, and preliminary assessment shown here. My direct contact stays private until I accept a shop.</span></label><Button className="min-h-11 rounded-xl" disabled={action.isPending || !e.ai_result || !shareApproved || (mode === "single" && !selected)} onClick={() => action.mutate({ type: "distribute", body: { mode, shopProfileId: selected, zip, approveSharing: shareApproved } })}><Send className="mr-2 h-4 w-4" /> Share for review</Button></div>}{responses.length ? <div className="mt-5 grid gap-3">{responses.map((r: any) => { const opp = (e.opportunities || []).find((x: any) => x.id === r.opportunity_id); const accepted = opp?.status === "accepted" || r.status === "accepted"; return <div key={r.id} className="rounded-xl border p-3"><div className="flex items-center gap-2"><Store className="h-4 w-4 text-primary" /><b className="flex-1">{opp?.company_name || "Participating shop"}</b><Status value={accepted ? "accepted" : "responded"} /></div><p className="mt-2 text-sm">{r.customer_note || "The shop has reviewed your record."}</p><p className="mt-2 text-xs text-muted-foreground">{r.expected_repair_timing || "Timing to be discussed"} · {r.warranty || "Warranty details available from shop"}</p>{!accepted && r.status === "sent" && <Button className="mt-3 min-h-11 w-full rounded-xl" onClick={() => action.mutate({ type: "accept-shop", body: { opportunityId: r.opportunity_id } })}>Accept this shop</Button>}{accepted && <p className="mt-3 flex items-center gap-2 text-xs font-semibold text-primary"><Check className="h-4 w-4" /> Shop accepted; contact handoff is complete.</p>}</div>})}</div> : e.status !== "draft" && <p className="mt-5 rounded-lg bg-muted p-3 text-sm text-muted-foreground">Waiting for participating shops to respond.</p>}</Card>
    </div></div></main></Layout>;
}

function ShopOpportunity() {
  const { id } = useParams<{ id: string }>(); const { toast } = useToast(); const qc = useQueryClient();
  const { data: o, isLoading, isError, refetch } = useQuery<any>({ queryKey: [`/api/repairmatch/shop/opportunities/${id}`] });
  const [form, setForm] = useState({ availability: "", inspectionRequest: "", expectedRepairTiming: "", warranty: "", towingAvailable: false, partsApproach: "", capabilitiesNote: "", customerNote: "" });
  const [reviewedLines, setReviewedLines] = useState<any[]>([]);
  const [formInitialized, setFormInitialized] = useState(false);
  const [linesInitialized, setLinesInitialized] = useState(false);
  useEffect(() => {
    if (o?.response && !formInitialized) {
      setForm({ availability: o.response.availability || "", inspectionRequest: o.response.inspection_request || "", expectedRepairTiming: o.response.expected_repair_timing || "", warranty: o.response.warranty || "", towingAvailable: Boolean(o.response.towing_available), partsApproach: o.response.parts_approach || "", capabilitiesNote: o.response.capabilities_note || "", customerNote: o.response.customer_note || "" });
      setFormInitialized(true);
    }
    if (o && !linesInitialized) {
      const sourceLines = o.reviewedLines?.length ? o.reviewedLines : o.reviewed_lines?.length ? o.reviewed_lines : o.lines || [];
      setReviewedLines(sourceLines.map((l: any) => ({ estimateLineId: l.estimateLineId || l.estimate_line_id || l.id, component: l.component || "", recommendation: l.recommendation || "inspect", bodyHoursLow: l.bodyHoursLow ?? l.body_hours_low ?? "", bodyHoursHigh: l.bodyHoursHigh ?? l.body_hours_high ?? "", refinishHoursLow: l.refinishHoursLow ?? l.refinish_hours_low ?? "", refinishHoursHigh: l.refinishHoursHigh ?? l.refinish_hours_high ?? "", mechanicalHoursLow: l.mechanicalHoursLow ?? l.mechanical_hours_low ?? "", mechanicalHoursHigh: l.mechanicalHoursHigh ?? l.mechanical_hours_high ?? "", partsAllowanceLow: l.partsAllowanceLow ?? l.parts_allowance_low ?? "", partsAllowanceHigh: l.partsAllowanceHigh ?? l.parts_allowance_high ?? "", inspectionRequired: Boolean(l.inspectionRequired ?? l.inspection_required), notes: l.notes || "" })));
      setLinesInitialized(true);
    }
  }, [o, formInitialized, linesInitialized]);
  const edit = (i: number, key: string, value: any) => setReviewedLines(lines => lines.map((line, index) => index === i ? { ...line, [key]: value } : line));
  const save = useMutation({ mutationFn: (status: string) => apiRequest("PUT", `/api/repairmatch/shop/opportunities/${id}/response`, { ...form, status, reviewedLines }), onSuccess: () => { toast({ title: "Response saved" }); qc.invalidateQueries({ queryKey: [`/api/repairmatch/shop/opportunities/${id}`] }); }, onError: (e: Error) => toast({ title: "Could not save response", description: e.message, variant: "destructive" }) });
  if (isLoading) return <Layout business><div className="mx-auto max-w-4xl h-56 animate-pulse rounded-2xl bg-muted" /></Layout>;
  if (isError || !o) return <Layout business><div className="mx-auto max-w-4xl"><ErrorState message="This opportunity is unavailable or expired." retry={() => refetch()} /></div></Layout>;
  return <Layout business><main className="mx-auto max-w-5xl"><Link href="/biz/repairmatch" className="mb-6 inline-flex min-h-11 items-center gap-2 text-sm font-semibold text-muted-foreground"><ArrowLeft className="h-4 w-4" /> Opportunities</Link><SectionTitle eyebrow="SHOP REVIEW" title={estimateTitle(o)} detail="Original AI lines remain read-only; your reviewed copy is attributed separately." /><div className="grid gap-5 lg:grid-cols-[1fr_380px]"><Card className={`${panel} p-5`}><h2 className="font-display text-xl font-bold">Original AI lines</h2><p className="mt-1 text-xs text-muted-foreground">Read-only source of the customer record.</p><div className="mt-4 grid gap-3">{(o.lines || []).map((l: any) => <div key={l.id} className="rounded-xl border bg-muted/30 p-3"><b>{l.component}</b><span className="ml-2 text-xs text-primary">{l.recommendation}</span><p className="mt-1 text-xs text-muted-foreground">{l.notes || "Confirm during physical inspection."}</p></div>)}</div><h2 className="mt-7 border-t pt-5 font-display text-xl font-bold">Editable shop review</h2><div className="mt-3 grid gap-3">{reviewedLines.map((line, i) => <div key={line.estimateLineId || i} className="rounded-xl border border-[hsl(39_82%_57%)]/40 bg-[hsl(39_82%_57%)]/5 p-3"><div className="grid gap-2 sm:grid-cols-2"><Field label="Component"><Input value={line.component} onChange={e => edit(i, "component", e.target.value)} /></Field><Field label="Recommendation"><select className="h-11 rounded-md border bg-background px-3" value={line.recommendation} onChange={e => edit(i, "recommendation", e.target.value)}>{["repair","replace","R&I","blend","inspect"].map(v => <option key={v}>{v}</option>)}</select></Field></div><div className="mt-2 grid grid-cols-2 gap-2"><Field label="Body low"><Input type="number" value={line.bodyHoursLow} onChange={e => edit(i, "bodyHoursLow", e.target.value === "" ? "" : Number(e.target.value))} /></Field><Field label="Body high"><Input type="number" value={line.bodyHoursHigh} onChange={e => edit(i, "bodyHoursHigh", e.target.value === "" ? "" : Number(e.target.value))} /></Field><Field label="Refinish low"><Input type="number" value={line.refinishHoursLow} onChange={e => edit(i, "refinishHoursLow", e.target.value === "" ? "" : Number(e.target.value))} /></Field><Field label="Refinish high"><Input type="number" value={line.refinishHoursHigh} onChange={e => edit(i, "refinishHoursHigh", e.target.value === "" ? "" : Number(e.target.value))} /></Field><Field label="Mechanical low"><Input type="number" value={line.mechanicalHoursLow} onChange={e => edit(i, "mechanicalHoursLow", e.target.value === "" ? "" : Number(e.target.value))} /></Field><Field label="Mechanical high"><Input type="number" value={line.mechanicalHoursHigh} onChange={e => edit(i, "mechanicalHoursHigh", e.target.value === "" ? "" : Number(e.target.value))} /></Field><Field label="Parts low"><Input type="number" value={line.partsAllowanceLow} onChange={e => edit(i, "partsAllowanceLow", e.target.value === "" ? "" : Number(e.target.value))} /></Field><Field label="Parts high"><Input type="number" value={line.partsAllowanceHigh} onChange={e => edit(i, "partsAllowanceHigh", e.target.value === "" ? "" : Number(e.target.value))} /></Field></div><label className="mt-2 flex min-h-11 items-center gap-2 text-sm"><Checkbox checked={line.inspectionRequired} onCheckedChange={v => edit(i, "inspectionRequired", Boolean(v))} /> Inspection required</label><Field label="Notes"><Textarea value={line.notes} onChange={e => edit(i, "notes", e.target.value)} /></Field></div>)}</div></Card><Card className={`${panel} p-5`}>{o.customer_contact ? <div className="mb-5 rounded-xl border border-primary/30 bg-primary/5 p-3"><p className="text-xs font-semibold uppercase tracking-wide text-primary">Customer accepted your shop</p><p className="mt-2 text-sm font-semibold">{o.customer_contact.name || "RepairMatch customer"}</p><p className="text-sm">{o.customer_contact.phone || "No phone provided"}</p><p className="text-sm">{o.customer_contact.email || "No email provided"}</p></div> : <div className="mb-5 flex items-start gap-2 rounded-xl bg-muted p-3 text-xs text-muted-foreground"><LockKeyhole className="mt-0.5 h-4 w-4 shrink-0" />Customer contact stays hidden until they accept your shop.</div>}<h2 className="font-display text-xl font-bold">Response</h2><div className="mt-5 grid gap-4">{[["availability","Availability"],["inspectionRequest","Inspection request"],["expectedRepairTiming","Expected repair timing"],["warranty","Warranty"],["partsApproach","Parts approach"],["capabilitiesNote","Capabilities note"],["customerNote","Note for customer"]].map(([key,label]) => <Field key={key} label={label}><Input value={(form as any)[key]} onChange={e => setForm(x => ({ ...x, [key]: e.target.value }))} /></Field>)}<label className="flex min-h-11 items-center gap-2 text-sm"><Checkbox checked={form.towingAvailable} onCheckedChange={v => setForm(x => ({ ...x, towingAvailable: Boolean(v) }))} /> Towing coordination available</label><Button variant="outline" className="min-h-11 rounded-xl" onClick={() => save.mutate("declined")} disabled={save.isPending}>Decline</Button><Button className="min-h-11 rounded-xl" onClick={() => save.mutate("sent")} disabled={save.isPending}>Send reviewed response <Send className="ml-2 h-4 w-4" /></Button><Button variant="ghost" className="min-h-11 rounded-xl" onClick={() => save.mutate("draft")} disabled={save.isPending}>Save draft</Button></div></Card></div></main></Layout>;
}